// Helper function to calculate the sum of even elements at odd indices
function SumEvenAtOddIndices(lst: seq<int>): int
    requires |lst| > 0
{
    var sum := 0;
    var i := 1; // Start with the first odd index
    while i < |lst|
        invariant 0 <= i <= |lst| // i is always a valid index
        invariant sum == SumEvenAtOddIndicesUpTo(lst, i)
    {
        if lst[i] % 2 == 0 {
            sum := sum + lst[i];
        }
        i := i + 2; // Move to the next odd index
    }
    return sum;
}

// Helper function to calculate the sum of even elements at odd indices up to index i
function SumEvenAtOddIndicesUpTo(lst: seq<int>, i: int): int
{
    var sum := 0;
    var j := 1;
    while j < i
        invariant 0 <= j <= i // j is always a valid index
        invariant sum == SumEvenAtOddIndicesUpTo(lst, j)
    {
        if lst[j] % 2 == 0 {
            sum := sum + lst[j];
        }
        j := j + 2; // Move to the next odd index
    }
    return sum;
}
